list_tax_zones.code:
var response = await client.TaxZones.ListTaxZonesAsync(
    new Dictionary<string, object?> { ["limit"] = 2 });
var body = (IReadOnlyDictionary<string, object?>)response.Map!;
foreach (var taxZone in ((IReadOnlyList<object?>)body["tax_zones"]!).Cast<IReadOnlyDictionary<string, object?>>())
    Console.WriteLine($"{taxZone["id"]} {taxZone["name"]}");

