var response = await client.TaxZones.CreateTaxZoneAsync(new Dictionary<string, object?>
{
    ["tax_zone"] = new Dictionary<string, object?>
    {
        ["name"] = "Sydney Metro", ["post_code"] = new List<object?> { "2000", "3000" },
        ["countries"] = new List<object?> { new Dictionary<string, object?> { ["id"] = 12 } },
        ["states"] = new List<object?> { new Dictionary<string, object?> { ["id"] = 67 } },
    },
});
var body = (IReadOnlyDictionary<string, object?>)response.Map!;
var taxZone = (IReadOnlyDictionary<string, object?>)body["tax_zone"]!;
Console.WriteLine(taxZone["id"]);

